update_rule.pseudocode:
if t == 0:
  if network_type == 'watts_strogatz':
    G = watts_strogatz_graph(N, k=mean_degree, p=rewiring_prob)
  elif network_type == 'barabasi_albert':
    G = barabasi_albert_graph(N, m=max(1, int(mean_degree/2)))
  else:
    G = watts_strogatz_graph(N, k=mean_degree, p=rewiring_prob)
  emit signal.network_graph = G
for each edge (u,v) in G:
  with prob=edge_churn_rate: rewire edge to random node preserving degree
for each node i in G:
  deg_i = degree(i)
  lambda_i = max(0.0, contact_rate_scale) * deg_i
  contacts_today_i ~ Poisson(lambda_i)
emit signal.contacts_today_counts = {i: contacts_today_i for all i}

for each person i:
  N_i = neighbors(i) from signal.network_graph
  if |N_i| > 0:
    neighbor_mean = mean(opinion_j for j in N_i)
  else:
    neighbor_mean = opinion_i
  eps ~ Normal(0, opinion_noise_std)
  opinion_new_i = stubbornness * opinion_i + (1 - stubbornness) * (influence_weight_neighbors * neighbor_mean + influence_weight_intrinsic * opinion_i)
  opinion_new_i = clip(opinion_new_i + eps, 0, 1)
  peer_pressure_i = mean(1.0 if adopted_j else 0.0 for j in N_i) if |N_i|>0 else 0.0
emit signal.updated_opinions = {i: opinion_new_i}
emit signal.peer_pressure = {i: peer_pressure_i}

if t < policy_start_day:
  inc = 0.0
elif t < policy_start_day + policy_ramp_days:
  inc = max_policy_incentive * (t - policy_start_day + 1) / policy_ramp_days
else:
  inc = max_policy_incentive
inc = clip(inc, 0, 1)
for each person i:
  effective_i = inc * max(0.0, min(1.0, compliance_prop_i * (0.5 + 0.5 * compliance_base)))
emit signal.policy_incentive_global = inc
emit signal.policy_pressure_per_agent = {i: effective_i}

for each person i:
  U_i = alpha_opinion_weight * opinion_i + beta_peer_weight * peer_pressure_i + gamma_policy_weight * policy_pressure_i - delta_cost_weight * cost_i + habit_persistence * (1 if adopted_i else 0)
  p_adopt_i = sigmoid((U_i - decision_threshold) / max(1e-6, decision_temperature))
  if adopted_i == 1:
    # persistence: allow drop with very low probability if U_i << threshold (optional; here disabled)
    adopted_new_i = 1
  else:
    adopted_new_i ~ Bernoulli(p_adopt_i)
  new_adopt_i = 1 if (adopted_new_i == 1 and adopted_i == 0) else 0
emit signal.updated_adoption_state = {i: adopted_new_i}
emit signal.new_adoptions_flag = {i: new_adopt_i}
